static bool lm_text_is_float_77000328(const char* s, int32_t n) {
    char* end = NULL;
    if (n == 0 || n >= 64 || (int32_t)strlen(s) != n) return false;
    if (s[0] == ' ' || s[0] == '\t' || s[0] == '\n' || s[0] == '\r' || s[0] == '\f' || s[0] == '\v') return false;
    (void)strtod(s, &end);
    return end == s + n;
}
